    .qspi_xip_axi_rready(s_if[S_SPI_NOR].rready),
    .irq(apb_irq)
  );
  assign s_if[S_SPI_NOR].bid[7:4] = '0;    // the NoC keeps the master ID itself
  assign s_if[S_SPI_NOR].rid[7:4] = '0;    // the NoC keeps the master ID itself

  apb_sva #(.NAME("apb_apb_ext")) u_apb_apb_ext_sva (apb_apb_ext_if);
  initial uvm_config_db#(virtual apb_if)::set(null, "uvm_test_top.env.apb_apb_ext.*", "vif", apb_apb_ext_if);
  apb_sva #(.NAME("apb_venc_cfg")) u_apb_venc_cfg_sva (apb_venc_cfg_if);
  initial uvm_config_db#(virtual apb_if)::set(null, "uvm_test_top.env.apb_venc_cfg.*", "vif", apb_venc_cfg_if);
  apb_sva #(.NAME("apb_jpeg_cfg")) u_apb_jpeg_cfg_sva (apb_jpeg_cfg_if);
  initial uvm_config_db#(virtual apb_if)::set(null, "uvm_test_top.env.apb_jpeg_cfg.*", "vif", apb_jpeg_cfg_if);
  apb_sva #(.NAME("apb_npu_cfg")) u_apb_npu_cfg_sva (apb_npu_cfg_if);
  initial uvm_config_db#(virtual apb_if)::set(null, "uvm_test_top.env.apb_npu_cfg.*", "vif", apb_npu_cfg_if);

  // ---------------- DRAM channel ddr0: ddr4 model ----------------
  soc_ddr4_chan #(.NAME("ddr0"), .IDW(8), .TCK_PS(752), .CL(19), .CWL(14), .T_CCD_S(4), .T_CCD_L(7), .T_RCD(19), .T_RP(19), .T_RAS(43), .T_RC(62), .T_RRD_S(8), .T_RRD_L(9), .T_FAW(40), .T_WTR_S(4), .T_WTR_L(10), .T_WR(20), .T_RTP(10), .T_RFC(466), .T_REFI(10373), .NDEV(1)) u_ddr0 (
