    .s_rvalid(s_if[S_DDR0].rvalid),
    .s_rready(s_if[S_DDR0].rready)

  );

  // ---------------- DRAM channel ddr1: ddr4 model ----------------
  soc_ddr4_chan #(.NAME("ddr1"), .IDW(8), .TCK_PS(752), .CL(19), .CWL(14), .T_CCD_S(4), .T_CCD_L(7), .T_RCD(19), .T_RP(19), .T_RAS(43), .T_RC(62), .T_RRD_S(8), .T_RRD_L(9), .T_FAW(40), .T_WTR_S(4), .T_WTR_L(10), .T_WR(20), .T_RTP(10), .T_RFC(466), .T_REFI(10373), .NDEV(1)) u_ddr1 (
    .aclk(aclk), .aresetn(aresetn),
    .s_awid(s_if[S_DDR1].awid),
    .s_awaddr(s_if[S_DDR1].awaddr),
    .s_awlen(s_if[S_DDR1].awlen),
