    .s_araddr(s_if[S_DDR1].araddr),
    .s_arlen(s_if[S_DDR1].arlen),
    .s_arsize(s_if[S_DDR1].arsize),
    .s_arburst(s_if[S_DDR1].arburst),
    .s_arprot(s_if[S_DDR1].arprot),
    .s_arvalid(s_if[S_DDR1].arvalid),
    .s_arready(s_if[S_DDR1].arready),
    .s_rid(s_if[S_DDR1].rid),
    .s_rdata(s_if[S_DDR1].rdata),
