    dram_ready = 1'b1;
    `uvm_info("DRAM", "all DRAM channels initialised", UVM_LOW)
  end
  always @(u_ddr0.errors)
    if (u_ddr0.errors != 0)
      `uvm_error("DRAM", $sformatf("ddr0: DRAM device model reports %0d protocol / timing violations", u_ddr0.errors))
